def merge_intervals(intervals):
    """Merge overlapping or touching [start, end] intervals.

    Returns a new list of [start, end] pairs sorted by start. Input order
    doesn't matter and the input list is not modified. Intervals that merely
    touch (one ends exactly where the next starts) are merged too.
    """
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

