from intervals import merge_intervals


def test_returns_list():
    assert isinstance(merge_intervals([[1, 2]]), list)


def test_never_grows():
    assert len(merge_intervals([[1, 3], [2, 6]])) <= 2


def test_empty():
    assert merge_intervals([]) == []


def test_single_passthrough():
    assert merge_intervals([[4, 9]]) == [[4, 9]]
